import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, field, DEVICES, CalcInput, SET1 } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — экран', () => {
  for (const tag of DEVICES) {
    test(`3 зоны ввода + «תוצאות», lang=he и RTL, ползунок налога 0..50 = 23 #3e4835 ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);

      await expect(page.getByRole('heading', { level: 1, name: 'מחשבון כדאיות רכישת עסק' })).toBeVisible();
      for (const h of ['השקעה ראשונית', 'רווחיות', 'מימון', 'תוצאות']) {
        await expect(page.getByRole('heading', { level: 2, name: h, exact: true }), `H2 «${h}»`).toBeVisible();
      }
      await expect(page.locator('html')).toHaveAttribute('lang', 'he');
      await expect(page.locator('main')).toHaveCSS('direction', 'rtl');

      for (const name of Object.keys(SET1) as CalcInput[]) await expect(field(page, name), `поле #calc-${name}`).toBeVisible();

      const slider = page.getByRole('slider');
      await expect(slider).toHaveAttribute('aria-valuemin', '0');
      await expect(slider).toHaveAttribute('aria-valuemax', '50');
      await expect(slider).toHaveAttribute('aria-valuenow', '23');
    });
  }
});
